files.content:
:root {
  color-scheme: dark;
  --ink: #f4f0dd;
  --muted: #a8b0bb;
  --navy: #202b3d;
  --panel: #2a3850;
  --mint: #93e4c1;
  --gold: #f2c66d;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }

body {
  margin: 0;
  min-width: 360px;
  min-height: 100vh;
  background-color: var(--navy);
  background-image: radial-gradient(#52627b 1.5px, transparent 1.5px);
  background-size: 24px 24px;
  color: var(--ink);
  font: 16px/1.5 system-ui, sans-serif;
}

.page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 24px;
  padding: 32px 16px 20px;
}

.profile-card {
  width: min(100%, 420px);
  padding: 24px 28px 20px;
  text-align: center;
  background: var(--panel);
  border: 4px solid var(--ink);
  box-shadow: 8px 8px 0 #111a29, inset 0 0 0 4px #364660;
}

.card-topline, .eyebrow, .bio-label, footer {
  font-size: 14px;
  font-weight: 800;
  letter-spacing: .12em;
}
.card-topline { color: var(--mint); }
.pixel-dot { display: inline-block; width: 10px; height: 10px; margin-right: 7px; background: var(--gold); }
.avatar {
  width: 90px;
  height: 90px;
  display: grid;
  place-items: center;
  margin: 23px auto 12px;
  border: 4px solid var(--ink);
  background: var(--mint);
  box-shadow: 5px 5px 0 #172234;
}
.avatar-face { color: var(--navy); font-size: 44px; line-height: 1; }
.eyebrow { margin: 16px 0 3px; color: var(--gold); }
h1, .profile-title, .bio { margin: 0; }
h1 { font-size: clamp(27px, 8vw, 34px); line-height: 1.2; }
.profile-title { margin-top: 7px; color: var(--muted); }
.divider { display: flex; align-items: center; gap: 12px; margin: 20px 0; color: var(--gold); }
.divider::before, .divider::after { height: 2px; flex: 1; content: ""; background: #53637c; }
.bio-label { display: flex; justify-content: space-between; margin: 0 0 8px; color: var(--mint); text-align: left; }
.bio-label span { color: var(--muted); font-size: 13px; letter-spacing: normal; }
.bio { min-height: 72px; padding: 10px; color: var(--ink); text-align: left; background: #222f43; border: 2px solid #53637c; overflow-wrap: anywhere; }
.editable { border-radius: 2px; }
.editable:focus { outline: 2px solid var(--gold); outline-offset: 3px; }
.actions { display: flex; justify-content: center; gap: 12px; margin-top: 20px; }
.button { min-width: 112px; padding: 10px 16px; border: 2px solid var(--ink); font: inherit; font-weight: 800; cursor: pointer; transition: transform .12s, filter .12s, box-shadow .12s; }
.button-primary { color: var(--navy); background: var(--mint); box-shadow: 3px 3px 0 #111a29; }
.button-secondary { color: var(--ink); background: #3b4a63; box-shadow: 3px 3px 0 #111a29; }
.button:hover { filter: brightness(1.1); transform: translateY(-1px); }
.button:focus-visible { outline: 3px solid var(--gold); outline-offset: 3px; }
.button:active { box-shadow: 0 0 0 #111a29; transform: translate(3px, 3px); }
.saved-message { margin: 13px 0 0; color: var(--mint); font-weight: 800; }
.hint { margin: 12px 0 0; color: var(--muted); font-size: 14px; }
footer { color: #b8c2d0; text-align: center; }
footer span { margin-left: 5px; color: var(--gold); }

@media (max-width: 400px) {
  .profile-card { padding: 20px 18px 18px; }
  .button { min-width: 0; flex: 1; }
}

const nameField = document.querySelector("#profile-name");
const titleField = document.querySelector("#profile-title");
const bioField = document.querySelector("#profile-bio");
const bioCount = document.querySelector("#bio-count");
const savedMessage = document.querySelector("#saved-message");
const fields = [nameField, titleField, bioField];
let savedValues = fields.map((field) => field.textContent.trim());

function updateBioCount() {
  const text = bioField.textContent.slice(0, 120);
  if (bioField.textContent !== text) bioField.textContent = text;
  bioCount.textContent = `${text.length} / 120`;
}

bioField.addEventListener("input", () => {
  updateBioCount();
  savedMessage.hidden = true;
});

for (const field of fields) {
  field.addEventListener("input", () => { savedMessage.hidden = true; });
  field.addEventListener("keydown", (event) => {
    if (field !== bioField && event.key === "Enter") {
      event.preventDefault();
      field.blur();
    }
  });
}

document.querySelector("#save-button").addEventListener("click", () => {
  updateBioCount();
  savedValues = fields.map((field) => field.textContent.trim());
  savedMessage.hidden = false;
});

document.querySelector("#cancel-button").addEventListener("click", () => {
  fields.forEach((field, index) => { field.textContent = savedValues[index]; });
  updateBioCount();
  savedMessage.hidden = true;
});

updateBioCount();
